<?php
require_once 'config.php'; require_once 'includes/auth_check.php'; require_once 'includes/security.php';
if(($_SESSION['user_role']??'')!=='admin'){http_response_code(403);exit('Administrator access required.');}
$logs=$conn->query("SELECT a.*,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 100")->fetch_all(MYSQLI_ASSOC);
$overdue=$conn->query("SELECT c.id,c.reference_no,c.subject,c.priority,c.status,c.sla_due_at,d.name department_name FROM complaints c LEFT JOIN departments d ON d.id=c.department_id WHERE c.sla_due_at<NOW() AND c.status NOT IN ('Resolved','Rejected') ORDER BY c.sla_due_at ASC LIMIT 50")->fetch_all(MYSQLI_ASSOC);
$departments=$conn->query("SELECT COALESCE(d.name,'Unassigned') department_name,COUNT(c.id) total,SUM(c.status='Resolved') resolved,ROUND(AVG(CASE WHEN c.feedback_rating IS NOT NULL THEN c.feedback_rating END),2) avg_rating FROM complaints c LEFT JOIN departments d ON d.id=c.department_id GROUP BY d.id,d.name ORDER BY total DESC")->fetch_all(MYSQLI_ASSOC);
$officers=$conn->query("SELECT u.full_name,COALESCE(d.name,'Unassigned') department_name,COUNT(c.id) assigned,SUM(c.status='Resolved') resolved,SUM(c.status NOT IN ('Resolved','Rejected')) active FROM users u LEFT JOIN departments d ON d.id=u.department_id LEFT JOIN complaints c ON c.officer_id=u.id WHERE u.role='officer' GROUP BY u.id,u.full_name,d.name ORDER BY assigned DESC")->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Audit & Analytics | Grievance Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"></head><body class="bg-light"><div class="d-flex min-vh-100"><?php include 'includes/sidebar.php';?><main class="flex-grow-1"><header class="bg-white border-bottom p-3 d-flex justify-content-between align-items-center"><div><h4 class="mb-0">Audit & Performance Dashboard</h4><small class="text-muted">Accountability, SLA health, and workload evidence.</small></div><div class="btn-group"><a class="btn btn-outline-primary btn-sm" href="admin_export.php?format=csv"><i class="bi bi-filetype-csv"></i> CSV</a><a class="btn btn-outline-primary btn-sm" href="admin_export.php?format=pdf"><i class="bi bi-file-earmark-pdf"></i> PDF</a></div></header><div class="container-fluid p-4"><div class="row g-4 mb-4"><div class="col-lg-6"><div class="card border-0 shadow-sm h-100"><div class="card-header bg-white fw-semibold"><i class="bi bi-alarm text-danger me-2"></i>Overdue SLA complaints <span class="badge text-bg-danger"><?=count($overdue)?></span></div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Reference</th><th>Priority</th><th>Due</th><th></th></tr></thead><tbody><?php foreach($overdue as $c):?><tr><td><a href="view_complaint.php?id=<?=$c['id']?>"><?=e($c['reference_no'])?></a><div class="small text-muted"><?=e($c['subject'])?></div></td><td><?=e($c['priority'])?></td><td class="text-danger small"><?=e($c['sla_due_at'])?></td><td><a class="btn btn-sm btn-outline-danger" href="escalate_complaint.php?id=<?=$c['id']?>">Escalate</a></td></tr><?php endforeach;?><?php if(!$overdue):?><tr><td colspan="4" class="text-center text-muted py-4">No overdue cases.</td></tr><?php endif;?></tbody></table></div></div></div><div class="col-lg-6"><div class="card border-0 shadow-sm h-100"><div class="card-header bg-white fw-semibold"><i class="bi bi-building me-2"></i>Department performance</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Department</th><th>Total</th><th>Resolved</th><th>Avg rating</th></tr></thead><tbody><?php foreach($departments as $d):?><tr><td><?=e($d['department_name'])?></td><td><?=$d['total']?></td><td><?=$d['resolved']?></td><td><?=e($d['avg_rating']??'—')?>/5</td></tr><?php endforeach;?></tbody></table></div></div></div></div><div class="row g-4 mb-4"><div class="col-lg-6"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold"><i class="bi bi-person-badge me-2"></i>Officer workload</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Officer</th><th>Dept.</th><th>Assigned</th><th>Active</th><th>Resolved</th></tr></thead><tbody><?php foreach($officers as $o):?><tr><td><?=e($o['full_name'])?></td><td><?=e($o['department_name'])?></td><td><?=$o['assigned']?></td><td><?=$o['active']?></td><td><?=$o['resolved']?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-6"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold">Audit events</div><div class="table-responsive" style="max-height:310px"><table class="table table-sm mb-0"><thead><tr><th>When</th><th>Actor</th><th>Action</th><th>Description</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td class="small text-muted"><?=e($log['created_at'])?></td><td><?=e($log['full_name']??'System')?></td><td><span class="badge text-bg-secondary"><?=e($log['action'])?></span></td><td class="small"><?=e($log['description'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div></main></div></body></html>
